/**
 * Recursion and divide & conquer: 25 company-tagged interview problems.
 *
 * Test-case expected outputs are literals computed with independent brute-force checkers (different algorithms
 * from the reference solutions). Large "performance" inputs are generated with a seeded PRNG so they are identical
 * on every machine.
 */

import { code, type ProblemSpec } from "../../problemHelpers";

/** Deterministic PRNG (mulberry32): returns an integer in [0, bound). */
function seededRandom(seed: number): (bound: number) => number {
  let state = seed >>> 0;
  return (bound: number) => {
    state = (state + 0x6d2b79f5) >>> 0;
    let t = state;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return Math.floor((((t ^ (t >>> 14)) >>> 0) / 4294967296) * bound);
  };
}

function randomString(seed: number, length: number, alphabet: string): string {
  const next = seededRandom(seed);
  return Array.from({ length }, () => alphabet[next(alphabet.length)]).join("");
}

function randomInts(seed: number, length: number, low: number, high: number): number[] {
  const next = seededRandom(seed);
  return Array.from({ length }, () => low + next(high - low + 1));
}

type Case = { input: string; expectedOutput: string; isHidden: boolean };
const T = (input: string, expectedOutput: string, isHidden = true): Case => ({ input, expectedOutput, isHidden });

/** Builds `examples` from the visible cases (so they always match exactly) plus the hidden `testCases`. */
function build(cases: Case[], explanations: string[] = []) {
  const examples = cases
    .filter((c) => !c.isHidden)
    .map((c, i) => ({
      input: c.input,
      output: c.expectedOutput,
      ...(explanations[i] ? { explanation: explanations[i] } : {}),
    }));
  return { examples, testCases: cases };
}

