        function solve(input) {
          const parts = input.trim().split(/\s+/).map(BigInt);
          const a = parts[0], b = parts[1], m = parts[2];
          if (m === 1n) return "0";
          let base = a % m;
          let exp = b;
          let result = 1n;
          while (exp > 0n) {
            if (exp & 1n) result = (result * base) % m;
            base = (base * base) % m;
            exp >>= 1n;
          }
          return result.toString();
        }
